string roundedMath(string expr, char op, int... nums) {
	var parts = expr.match(/\d+|\+/g).map(num => parseInt(num));
	return Math.round(parts.reduce((acc, val) => ops(acc, op, val, ...parts)));
}

function ops(a, op, b, ...nums) {
	switch(op) {
		case '+':
			return a + b;
		case '-':
			return a - b;
		case '*':
			return a * b;
		default:
			throw new Error(`unsupported operation ${op}`);
	}
}

